const sampleQuestions:Question[]=[
  {question:"Quel est le premier réflexe avant de commencer l’activité ?",options:["Présenter l’objectif et les règles","Distribuer les réponses","Commencer sans consigne"],correct:0,explanation:"Une consigne claire sécurise les apprenants et facilite leur engagement."},
  {question:"Comment vérifier la compréhension ?",options:["Faire reformuler la consigne","Parler plus vite","Supprimer la pratique"],correct:0,explanation:"La reformulation permet de repérer immédiatement une incompréhension."},
  {question:"Quel retour aide le mieux à progresser ?",options:["Un retour précis et constructif","Une note seule","Aucun retour"],correct:0,explanation:"Un retour concret indique les acquis et le prochain axe de progrès."}
];
const textAnswerFormats=new Set(["Mots mêlés","Pendu","Épeler le mot","Mots croisés","Tapez la réponse","Anagramme"]);
const flashcardFormats=new Set(["Retournez les tuiles","Fiches de révision","Cartes mémoire","Cartes aléatoires"]);
const speedFormats=new Set(["Quiz télévisé","Poursuite dans le labyrinthe","Fruits volants"]);
function starterQuestionsFor(type:string):Question[]{
  if(type==="Vrai ou faux")return [
    {question:"Une consigne doit être comprise avant de commencer.",options:["Vrai","Faux"],correct:0,explanation:"Faire reformuler la consigne permet de vérifier la compréhension."},
    {question:"Une erreur empêche toujours de progresser.",options:["Vrai","Faux"],correct:1,explanation:"L’erreur analysée et corrigée est une étape utile de l’apprentissage."},
    {question:"Un retour précis aide à améliorer sa pratique.",options:["Vrai","Faux"],correct:0,explanation:"Un retour concret indique ce qui est acquis et ce qui reste à travailler."}
  ];
  if(textAnswerFormats.has(type))return [
    {question:"Quel mot désigne ce que l’apprenant doit savoir faire à la fin ?",options:["objectif","résultat","chapitre"],correct:0,explanation:"Un objectif pédagogique décrit la capacité attendue à la fin de l’apprentissage."},
    {question:"Complétez : une consigne claire facilite la…",options:["compréhension","vitesse","notation"],correct:0,explanation:"La clarté de la consigne facilite d’abord la compréhension."},
    {question:"Quel mot désigne le retour donné après une réponse ?",options:["feedback","hasard","silence"],correct:0,explanation:"Le feedback explique la réussite ou l’erreur et aide à progresser."}
  ];
  if(flashcardFormats.has(type))return [
    {question:"Objectif pédagogique",options:["Ce que l’apprenant saura faire à la fin","Une note finale","Le titre du cours"],correct:0,explanation:"Le verso donne une définition simple et directement mémorisable."},
    {question:"Feedback",options:["Retour qui explique comment progresser","Chronomètre de l’activité","Liste des participants"],correct:0,explanation:"Un bon feedback est précis, constructif et exploitable."},
    {question:"Évaluation formative",options:["Vérification en cours d’apprentissage","Diplôme final","Règlement intérieur"],correct:0,explanation:"Elle sert à repérer les acquis et à ajuster l’apprentissage."}
  ];
  if(type==="Classement par rang"||type==="Démêler")return [
    {question:"Remettez la démarche dans l’ordre.",options:["Observer → comprendre → agir → contrôler","Agir → observer → ignorer → finir","Contrôler → agir → lire → commencer"],correct:0,explanation:"La démarche commence par l’observation et se termine par le contrôle."},
    {question:"Classez les étapes d’une consigne efficace.",options:["Objectif → action → critère de réussite","Correction → hasard → action","Note → silence → objectif"],correct:0,explanation:"L’apprenant doit connaître le but, l’action attendue et le critère de réussite."},
    {question:"Remettez la phrase en ordre.",options:["Je lis la consigne avant de répondre","Répondre avant je consigne la lis","Consigne réponds je puis"],correct:0,explanation:"La phrase correcte respecte l’ordre logique et grammatical."}
  ];
  if(type==="Apparier"||type==="Paire ou pas de paire"||type==="Diagramme étiqueté")return [
    {question:"Associez « Objectif » à la bonne définition.",options:["Capacité attendue","Durée de pause","Couleur du support"],correct:0,explanation:"L’objectif indique ce que l’apprenant devra savoir faire."},
    {question:"Associez « Consigne » à sa fonction.",options:["Indiquer l’action à réaliser","Donner uniquement la note","Remplacer l’exercice"],correct:0,explanation:"La consigne explique clairement la tâche attendue."},
    {question:"Associez « Correction » à son utilité.",options:["Comprendre et progresser","Cacher la réponse","Allonger l’activité"],correct:0,explanation:"La correction rend l’erreur compréhensible et améliore la mémorisation."}
  ];
  if(type==="Roue du défi")return [
    {question:"Faites tourner la roue pour tirer un défi sur les consignes.",options:["Reformulez une consigne avec vos mots","Donnez un exemple de consigne claire","Repérez un mot important dans la consigne","Expliquez le critère de réussite"],correct:0,explanation:"La reformulation et l’exemple permettent de vérifier que la consigne est réellement comprise."},
    {question:"Faites tourner la roue pour tirer un défi sur la mémorisation.",options:["Citez trois idées à retenir","Inventez une astuce mémo","Expliquez la notion à un collègue","Dessinez la méthode en quatre étapes"],correct:0,explanation:"Produire une réponse, une astuce ou un schéma renforce la mémorisation active."},
    {question:"Faites tourner la roue pour tirer un défi de mise en pratique.",options:["Mimez le premier geste à réaliser","Décrivez une situation professionnelle","Corrigez volontairement une mauvaise pratique","Proposez un contrôle final"],correct:0,explanation:"La mise en pratique aide à transférer les connaissances dans une situation professionnelle."}
  ];
  return sampleQuestions.map(question=>({...question,options:[...question.options]}));
}
