type IconName="home"|"book"|"game"|"chart"|"plus"|"search"|"bell"|"dots"|"play"|"spark"|"plug"|"download"|"users"|"wand"|"expand"|"upload"|"image"|"lock"|"logout"|"shield"|"trash";
